def solve():
    balanced_equation = "KNO3(s) -> K+(aq) + NO3-(aq)"
    initial_Kc = step_152(
        balanced_equation=balanced_equation,
        eq_amounts={
            "KNO3(s)": V_initial,
            "K+(aq)": n_dissolved_initial,
            "NO3-(aq)": n_dissolved_initial,
        },
        volume=V_initial,
    )["equilibrium_constant"]
    temperature_shift = step_167(
        balanced_equation=balanced_equation,
        delta_h=abs(n_total),
        change="increase the temperature",
    )["direction_of_shift"]
    full_dissolution_shift = step_157(
        equilibrium_constant=Kc_T2,
        balanced_equation=balanced_equation,
        current_concentrations={
            "KNO3(s)": 1.0,
            "K+(aq)": n_total / V_initial,
            "NO3-(aq)": n_total / V_initial,
        },
    )["direction_of_shift"]
    if temperature_shift == "forward" and full_dissolution_shift == "forward":
        return 0.0
    required_volume = V_initial * n_total / (
        n_dissolved_initial * math.sqrt(Kc_T2 / initial_Kc)
    )
    return max(0.0, required_volume - V_initial)

